        "508": { n: "Vertikalni i horizontalni spojevi zidanja", t: "STO NOSTROY 2.9.136-2013 tabela 9.1, Tehnička karta\nRačunska debljina horizontalnih i vertikalnih spojeva usvaja se 2 +/- 1 mm. Stvarna debljina spoja u konstrukciji ne treba da bude veća od 3 mm" },
        "509": { n: "Ravnost i uklanjanje prašine sa nalegajuće površine svakog reda zidanja", t: "STO NOSTROY 2.9.136-2013 tač.6.1.2, Tehnička karta\nSvaki red mora se provoditi na ravnost nalegajuće površine. Razlike između susednih blokova otkrivene letvom uklanjaju se brušenjem. Brušena površina mora biti oslobođena prašine." },
        "510": { n: "Debljina donjeg izravnjavajućeg sloja zidanja prvog reda", t: "STO NOSTROY 2.9.136-2013 tač.6.1.4, Tehnička karta\nZa prvi red debljina izravnjavajućeg neprekidnog malterskog spoja može varirati od 6 do 30 mm u zavisnosti od površine podloge." },
        "511": { n: "Ravnomerno nanošenje lepljivog rastvora, popuna spojeva rastvorom bez preskoka", t: "SP 70.13330.2012; Tehnička karta\nPropusti u nanošenju lepka nisu dozvoljeni" },
        "512": { n: "Pravilnost vezivanja spojeva", t: "SP 70.13330.2012 tač. 9.2.1, Tehnička karta\nPomeranje vertikalnih spojeva u redosledu ne manje od 100 mm." },
        "513": { n: "Armiranje zidanja", t: "STO NOSTROY 2.9.136-2013 tač.5.1.8, 5.3.2.15, 5.3.3.3\nPrema projektu. Svaki 3. red + otvori\n- armiranje pojedinačnim šipkama periodičnog profila izvodi se u malterom ispunjenim šlicevima izrađenim u nalegajućoj površini armiranog reda zidanja;\n- moguća je upotreba armaturnih rešetki za tanki spoj, izrađenih od korozivno-otporne ili zaštićene čelične trake radne armature debljine ne veće od 2 mm, spojenih zavarenom okruglom žicom;\n- moguće je armiranje zidanja pojedinačnim šipkama od trakaste korozivno-otporne ili zaštićene perforirane čelične trake debljine ne veće od 2 mm" },
        "514": { n: "Kontrola debljine zidova", t: "STO NOSTROY 2.9.136-2013 tabela 9.1;\nTehnička karta\nTolerancija «- 5 ; +5 mm»" },
        "515": { n: "Popunjavanje zazora između poslednjeg reda zidanja i vertikalnih elemenata zgrade", t: "Tehnička karta, prema projektu" },
        "516": { n: "Izrada nadvratnika/nadprozornika prema projektu i normativima", t: "SP 70.13330.2012; Tehnička karta, Projekat\nPri širini otvora do 1 m - oslanjanje levo i desno min. 100 mm. Ne preporučuje se da se pod oslonačkim delom nalazi vertikalni spoj pregradnih blokova.\nPri širini otvora do 1,1 m - oslanjanje levo i desno min. 100 mm, i po celoj dužini na armaturu klase AIII prema zidu sa obaveznim vertikalnim malterskim spojem. Armatura se pričvršćuje u armiranobetonski zid na preporučenu dubinu od 80 mm i uvlačenjem drugog kraja šipke u zidanje ne manje od 250 mm,\nPri širini do 1,6 m - stegnuti u zidanju po tipu konzole sa oslanjanjem ne manjim od 400 mm (1/3) sa donjim armiranjem metalnom armaturom klase A-III sa uvlačenjem krajnjih delova armaturne šipke ne manje od 250 mm u konstrukciju zidanja." },
        "517": { n: "Slabljenje kamenih konstrukcija - brazdama, šlicevima, nišama, otvorima.", t: "SP 70.13330.2012 tač. 9.1.4; Tehnička karta" },
        "518": { n: "Broj i pravilnost postavljanja anker elemenata (zid, plafon)", t: "Projekat, PIR, Tehnička karta\nKorak pričvršćivanja svaka 2-3 kamena.\nArmatura prečnika 6-8 mm.\nDužina šipke ne manja od 250 mm." },
        "519": { n: "Odstupanje ravni zidova i uglova od vertikale", t: "SP 70.13330.2012 tabela 9.8; Tehnička karta\nTolerancija ne veća od 10 mm na celu visinu sprata" },
        "520": { n: "Neravnine na vertikalnoj površini zidanja utvrđene prislanjanjem letve dužine 2 m", t: "SP 70.13330.2012 tabela 9.8; Tehnička karta\nTolerancija ne veća od 10 mm." },
        "521": { n: "Zidanje blokova bez zagađenja, izlivanja i udubljenja.", t: "SP 70.13330.2012; Tehnička karta" },
        "522": { n: "Odstupanje po širini pregradnih stubova (parapeta)", t: "SP 70.13330.2012 tabela 9.8; Tehnička karta\nTolerancija od 0 do «-15 mm»" },
        "523": { n: "Odstupanje po širini otvora", t: "SP 70.13330.2012 tabela 9.8; Tehnička karta\nTolerancija od 0 do «+15 mm»" },
        "524": { n: "Pomeranje od projektnog položaja obeležnih osa", t: "SP 70.13330.2012 tabela 9.8; Tehnička karta\nTolerancija – 10 mm" },
        "525": { n: "Pomeranje vertikalnih osa prozorskih otvora od vertikale", t: "SP 70.13330.2012 tabela 9.8;\nTolerancija – 20 mm" },
        "526": { n: "Odstupanje visinskih kota donjeg dela oslonačkih površina nadvratnika", t: "SP 70.13330.2012 tabela 9.8; Tehnička karta\nTolerancija «- 10 mm»" },
        "527": { n: "Odstupanje od horizontale postavljenih nadvratnika", t: "SP 70.13330.2012; Tehnička karta\nTolerancija - 10 mm" },

