        "602": { n: "Materijali se koriste u skladu s projektom ili su usaglašeni. Sertifikati", t: "SP 48.13330.2019 Prilog B, tač. B.1. Projekat" },
        "603": { n: "Izvođački crteži izvedenih radova", t: "SP 70.13330 tač.3.5, 3.23" },
