        "605": { n: "Celovitost trake za brtvljenje", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). bez oštećenja" },
        "606": { n: "Čistoća trake za brtvljenje", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Traka za brtvljenje pre betoniranja mora biti pažljivo očišćena od prljavštine, leda" },
        "607": { n: "Postavljanje simetrično, u sredinu radnih spojnica", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). odstupanje od projektnog položaja ≤ 30 mm" },
        "608": { n: "Rastojanje do ivice konstrukcije", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). ≥ 75 mm" },
        "609": { n: "Vrednost preklopa spojeva", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). ≥ 50 mm" },
        "610": { n: "Kvalitet spojeva, zatvorena kontura", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Čvrsta veza elemenata, zatvoren prostor po celom obimu" },
        "611": { n: "Korak postavljanja pričvrsnih elemenata", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Od 200 do 250 mm" },
        "612": { n: "Spojevi konstrukcija", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Ne manje od 30 mm" },
        "613": { n: "Priprema površine", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Traka se postavlja na pripremljenu betonsku površinu pre montaže oplate, u centru radne spojnice" },
        "614": { n: "Zaptivanje spojeva i uglova", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Preko zavarenog šva navariti PVC traku širine ne manje od 25 mm radi zaptivanja i ojačanja spoja trake (traka se navaruje sa obe strane šva)" },
        "615": { n: "Spajanje trake / kvalitet zavarenog šva", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Spoj na spoj. Spojevi i uglovi trake zavaruju se posebnim aparatom za zavarivanje. Kontrola na prosvet. Za provere se može koristiti elektroiskrivi defektoskop" },
        "616": { n: "Celovitost trake", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Bez proboja, zaseka i sl." },
        "617": { n: "Korak pričvršćivanja za armaturni skelet", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). 200-300 mm" },
        "618": { n: "Rastojanje do armature", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). ≥ 20 mm" },
        "619": { n: "Odstupanje od ose spoja", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). ≤ 10 mm" },
        "620": { n: "Zavijanje ankera trake", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). ≤ 10 mm" },
        "621": { n: "Priprema površine za montažu", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Betonska površina mora biti očišćena od prašine, zemlje, leda, boje i drugih strana materijala" },
        "622": { n: "Dužina postavljenog segmenta", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). ≤ 6 m" },
        "623": { n: "Vrednost preklopa", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). ≥ 150 mm" },
        "624": { n: "Korak postavljanja pričvrsnih elemenata", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). 150-200 mm" },
        "625": { n: "Odstupanje od projektnog položaja u ravni spoja", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). ≤ 50 mm" },
        "626": { n: "Rastojanje do ivice konstrukcije u osnovi", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). ≥ 75 mm" },
        "627": { n: "Rastojanje do površine na koju se vrši montaža", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). ≤ 3 mm" },
        "628": { n: "Kvalitet spajanja cevčica", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Čvrsta veza elemenata" },
        "629": { n: "Rastojanje od mesta izlaska cevčica do spoja", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). ≥ 200 mm" },
        "630": { n: "Montaža kutija", t: "Postojanje kutija" },
        "631": { n: "Postavljanje čepova", t: "Postojanje čepova" },
        "632": { n: "Proporcija mešanja", t: "Kompletom (prema probnom uzorku). Pre samog utiskivanja rastvora u posebnu posudu se uzima proba i provera vreme geliranja" },
        "633": { n: "Prohodnost cevčica", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Potpuna, prema pritisku. Pre početka injektiranja neophodno je provoditi prohodnost cevčice vodom ili komprimovanim vazduhom iz kompresora" },
        "634": { n: "Pritisak injektiranja", t: "≤ 80 atm. Ne dozvoliti porast pritiska u sistemu iznad 80 atm.; po potrebi injektirati sa prekidima, održavajući pritisak u sistemu u opsegu od 20 do 40 atm" },
        "635": { n: "Potrošnja injekcione smole", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). ≤ 1,5 l/m.d." },
        "636": { n: "Izlazak injekcione smole iz ravni spoja", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). 50% dužine spoja" },
        "637": { n: "Temperaturni režim", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Radovi se izvode na temperaturi okoline i površine konstrukcije ne nižoj od +5°S." },
        "638": { n: "Zadelavanje otvora u betonu", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Pripremne mere za uklanjanje konusa, PVC cevčica i zadelavanje otvora po celoj debljini konstrukcije reparaturnim materijalom" },
        "639": { n: "Pripremljenost površine podloge pre nanošenja", t: "Interni standard kompanije. Kvalitet površine (nabori, izbočine) ne više od 2 mm. Dozvoljene su rupice ili šupljine dubine ne veće od 5 mm; sa površine betona treba ukloniti cementno mleko, prljavštinu, masnoću, bitumenske i uljane mrlje i ostala zaprljanja" },
        "640": { n: "Raspored spojeva i popuna šlica", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). U vidu šlica dimenzije 30x30 mm i njihova popuna posebnim neskupljajućim reparaturnim materijalom. Raspored spojeva i popuna šlica reparaturnim materijalom" },
        "641": { n: "Debljina sloja", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Ne manje od 2 sloja. Nanošenje drugog sloja pod pravim uglom u odnosu na prvi, debljina jednog sloja ne manja od 1 mm" },
        "642": { n: "Poštovanje temperaturno-vlažnosnog režima nakon nanošenja", t: "Interni standard kompanije (tehnička specifikacija proizvođača (TU)). Naredna dva dana temperatura vazduha i površine podloge mora biti ne niža od +5°S i ne viša od +30°S. U procesu očvršćavanja (ne manje od 24 sata) površinu je potrebno zaštititi od kiše, dugotrajnog izlaganja direktnim sunčevim zracima i mrznjenja." },

        "701": { n: "Dnevnik ulazne kontrole korišćenih materijala", t: "SP 48.13330.2019 tač. 3.1, Prilog B.1" },
        "702": { n: "Materijali se koriste u skladu s projektom ili su usaglašeni", t: "SP 48.13330.2019 Prilog B, tač. B.1, stavka 7; Projekat" },
