        "705": { n: "Postojanje usaglašenog PIR", t: "SP 70.13330 tač.3.3" },
        "706": { n: "Čišćenje podloge", t: "STO NOSTROY 2.9.157-2014 tač.8.3.1\nPodloga mora biti očišćena od otpada, prašine, prljavštine i leda" },
        "707": { n: "Kvalitet cigle", t: "GOST 530-2012; Projekat\nMarka, geometrija, spoljašnji nedostaci — prema GOST 530" },
        "708": { n: "Kvalitet maltera", t: "SP 82-101-98\nMarka mora odgovarati projektu" },
        "709": { n: "Hidroizolacija podloge (ako postoji)", t: "SP 15.13330.2020 tač. 9.8" },
        "710": { n: "Debljina spojeva", t: "SP 70.13330.2012 tač. 9.1.12, 9.2.4:\n• Horizontalni — 12 mm\n• Vertikalni — 10 mm\nTolerancija ±2 mm (faktički 10–14 mm i 8–12 mm)" },
        "711": { n: "Vertikalnost zidova", t: "SP 70.13330.2012 tabela 9.8:\nOdstupanje ≤ 10 mm po spratu" },
        "712": { n: "Horizontalnost redova", t: "SP 70.13330.2012 (tabela 9.8):\nOdstupanje ≤ 10 mm na 10 m" },
        "713": { n: "Vezivanje spojeva", t: "SP 70.13330.2012 (tač. 9.2.1), tehnička karta:\nPomeranje ≥ 1/4 opeke\nZa redove na kant — ≥ 60 mm" },
        "714": { n: "Prozorski/vratni otvori", t: "SP 70.13330.2012 (tabela 9.8):\nŠirina otvora (od 0 do +15 mm)" },
        "715": { n: "Pomeranje zidova od osa u osnovi", t: "SP 70.13330.2012 (tabela 9.8)\n≤ 10 mm — za noseće zidove;\n≤ 15 mm — za pregradne zidove" },
        "716": { n: "Pomeranje osa prozorskih/vratnih otvora", t: "SP 70.13330.2012 tabela 9.8\nPomeranje vertikalnih osa prozorskih otvora od vertikale: 20 mm;\npomeranje osa konstrukcija od obeležnih osa: 10 mm" },
        "717": { n: "Kvalitet fugovanja", t: "SP 70.13330.2012 (tač. 9.2.5, 9.2.6), tehnička karta\nSpojevi bez šupljina, udubljenje ≤ 2 mm" },
        "718": { n: "Postojanje armature", t: "Projekat, Tehnička karta, SP 15.13330.2020 (tač. 9.82)\nMreže/šipke svaka 3–5 reda" },
        "719": { n: "Ankerovanje nosivih zidova za skelet/tavanice", t: "Projekat, Tehnička karta, SP 15.13330.2020 (tač. 9.41, 9.44, tabela 6.14), SP 70.13330.2012 (tač. 5.16.9)\nKorak ≤ 500 mm (po visini)" },
        "720": { n: "Zaštita od korozije", t: "SP 28.13330.2017 (tabela I1, K1)\nSP 70.13330.2012 (tač.9.2.14)\nPremaz ili debljina spoja ≥ 4 mm iznad armature (SP 70.13330.2012 tač.9.2.14)" },

        "801": { n: "Dnevnik ulazne kontrole korišćenih materijala", t: "SP 48.13330.2019 tač. 3.1, Prilog B.1" },
