        "1440": { n: "Prethodna regulacija", t: "GOST 34378-2018 tabela L1. Provera rada krila (otvaranje/zatvaranje bez napora)" },
        "1441": { n: "Zaštita proizvoda nakon montaže", t: "GOST 34378-2018 tač.7.4. TZ. Proizvodi zaštićeni (polikarbonat, privremeni okviri, samolepljiva folija, premaz tipa smart-skin)" },

        "1501": { n: "Dnevnik ulazne kontrole korišćenih materijala", t: "SP 48.13330.2019 tač. 3.1, Prilog B.1" },
        "1502": { n: "Materijali se koriste u skladu s projektom, etalon krila usaglašen", t: "SP 48.13330.2019 Prilog B, tač. B.1, stavka 7; Projekat, zapisnik o usaglašavanju" },
        "1503": { n: "Izvođački crteži izvedenih radova", t: "SP 70.13330 tač.3.5, 3.23" },
